mapper.update:
UPDATE inventory
SET cost_amount      = ROUND((quantity - #{qty}) * cost_price, 2),
    quantity         = quantity - #{qty},
    last_change_time = NOW(),
    version          = version + 1
WHERE goods_id = #{goodsId}
  AND store_id = #{storeId}

  AND quantity >= #{qty}

mapper.select:
SELECT goods_id, store_id, quantity, cost_price, cost_amount,
       last_change_time, version, update_time
FROM inventory
WHERE goods_id = #{goodsId}
  AND store_id = #{storeId}
FOR UPDATE
